header('Content-Type: application/json');

// Configuration
$to_email = "rajesh.ponpandi@gmail.com";
$subject_prefix = "[Website Contact] ";

if ($_SERVER["REQUEST_METHOD"] == "POST") {
    // Sanitize Input
    $name = strip_tags(trim($_POST["name"]));
    $email = filter_var(trim($_POST["email"]), FILTER_SANITIZE_EMAIL);
    $message = strip_tags(trim($_POST["message"]));

    // Validation
    if (empty($name) || empty($message) || !filter_var($email, FILTER_VALIDATE_EMAIL)) {
        http_response_code(400);
        echo json_encode(["success" => false, "message" => "Invalid input. Please complete all fields."]);
        exit;
    }

    // Email Headers
    $headers = "From: $name <$email>" . "\r\n";
    $headers .= "Reply-To: $email" . "\r\n";
    $headers .= "MIME-Version: 1.0" . "\r\n";
    $headers .= "Content-Type: text/plain; charset=UTF-8" . "\r\n";

    $subject = $subject_prefix . "Message from $name";

    $email_content = "Name: $name\n";
    $email_content .= "Email: $email\n\n";
    $email_content .= "Message:\n$message\n";

    // Send Mail
    if (mail($to_email, $subject, $email_content, $headers)) {
        echo json_encode(["success" => true, "message" => "Message sent successfully!"]);
    } else {
        http_response_code(500);
        echo json_encode(["success" => false, "message" => "Failed to send email."]);
    }
} else {
    http_response_code(403);
    echo json_encode(["success" => false, "message" => "Forbidden."]);
}
