    box-shadow: 0 8px 15px var(--shadow-medium);
}

.service-item img {
    width: 100%;
    height: 250px;
    object-fit: cover;
    border-bottom: 1px solid var(--border-color);
}

.service-item-content {
    padding: 2rem;
}

.service-item-content h3 {
    font-size: 1.8rem;
    color: var(--primary-color);
    margin-bottom: 1rem;
}

.service-item-content p {
    font-size: 1rem;
    color: #555;
    margin-bottom: 1.5rem;
}

/* Portfolio Page Specific */
.portfolio-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
    gap: 2rem;
    margin-top: 3rem;
}

.portfolio-item {
    background-color: var(--bg-white);
    border-radius: 8px;
    box-shadow: 0 4px 10px var(--shadow-light);
    overflow: hidden;
    text-align: center;
    transition: transform 0.3s ease, box-shadow 0.3s ease;
}

.portfolio-item:hover {
    transform: translateY(-5px);
    box-shadow: 0 8px 15px var(--shadow-medium);
}

.portfolio-item img {
    width: 100%;
    height: 220px;
    object-fit: cover;
}

.portfolio-item-content {
    padding: 1.5rem;
}

.portfolio-item-content h3 {
    font-size: 1.6rem;
    color: var(--primary-color);
    margin-bottom: 0.5rem;
}

.portfolio-item-content p {
    font-size: 0.95rem;
    color: #666;
}

/* Contact Page Specific */
.contact-grid {
    display: grid;
    grid-template-columns: 1fr;
    gap: 3rem;
    margin-top: 3rem;
}

.contact-info-block {
    background-color: var(--bg-white);
    padding: 2.5rem;
    border-radius: 8px;
    box-shadow: 0 4px 10px var(--shadow-light);
}

.contact-info-block h3 {
    color: var(--primary-color);
    font-size: 1.8rem;
    margin-bottom: 1.5rem;
}

.contact-info-block p {
    display: flex;
    align-items: center;
    margin-bottom: 1rem;
    font-size: 1.1rem;
    color: #555;
}

.contact-info-block p strong {
    min-width: 80px;
    display: inline-block;
    color: var(--primary-color);
}

.contact-form-wrapper {
    background-color: var(--bg-white);
    padding: 2.5rem;
    border-radius: 8px;
    box-shadow: 0 4px 10px var(--shadow-light);
}

.contact-form-wrapper h3 {
    color: var(--primary-color);
    font-size: 1.8rem;
    margin-bottom: 1.5rem;
}

.contact-form label {
    display: block;
    margin-bottom: 0.5rem;
    font-weight: bold;
    color: var(--primary-color);
}

.contact-form input[type="text"],
.contact-form input[type="email"],
.contact-form textarea {
    width: 100%;
    padding: 1rem;
    margin-bottom: 1.5rem;
    border: 1px solid var(--border-color);
    border-radius: 5px;
    font-size: 1rem;
    transition: border-color 0.3s ease;
}

.contact-form input:focus,
.contact-form textarea:focus {
    border-color: var(--secondary-color);
    outline: none;
    box-shadow: 0 0 0 3px rgba(0, 102, 204, 0.2);
}

.contact-form textarea {
    resize: vertical;
    min-height: 120px;
}

.contact-form button {
    width: 100%;
    padding: 1rem;
    font-size: 1.2rem;
    border-radius: 5px;
    cursor: pointer;
}

.map-container {
    background-color: var(--bg-white);
    padding: 1.5rem;
    border-radius: 8px;
    box-shadow: 0 4px 10px var(--shadow-light);
    margin-top: 3rem;
    text-align: center;
}

.map-container h3 {
    color: var(--primary-color);
    font-size: 1.8rem;
    margin-bottom: 1.5rem;
}

.map-container img {
    width: 100%;
    max-height: 400px;
    object-fit: cover;
    border-radius: 8px;
}

/* Footer */
footer {
    background-color: var(--primary-color);
    color: var(--text-color-light);
    padding: 3rem 0 1.5rem;
    margin-top: 4rem;
}

.footer-content {
    display: flex;
    flex-wrap: wrap;
    justify-content: space-between;
    gap: 2rem;
    margin-bottom: 2rem;
}

.footer-section {
    flex: 1 1 280px;
    min-width: 250px;
}

.footer-section h3 {
    font-size: 1.6rem;
    margin-bottom: 1.5rem;
    color: var(--accent-color);
}

.footer-section p,
.footer-section ul li a {
    font-size: 0.95rem;
    color: rgba(255, 255, 255, 0.8);
    line-height: 1.8;
}

.footer-section ul {
    list-style: none;
}

.footer-section ul li a:hover {
    color: var(--text-color-light);
    text-decoration: underline;
}

.footer-bottom {
    text-align: center;
    padding-top: 1.5rem;
    border-top: 1px solid rgba(255, 255, 255, 0.2);
    font-size: 0.9rem;
    color: rgba(255, 255, 255, 0.7);
}

/* Responsive Design */
@media (max-width: 992px) {
    .hero h1 {
        font-size: 3rem;
    }

    .hero p {
        font-size: 1.3rem;
    }

    .nav-menu {
        gap: 1.5rem;
    }

    .content-block {
        flex-direction: column !important;
    }

    .content-block:nth-of-type(even) {
        flex-direction: column !important; /* Override for smaller screens */
    }

    .content-block .image-wrapper, .content-block .text-content {
        padding: 0;
    }

    .footer-section {
        flex-basis: 45%;
    }
}

@media (max-width: 768px) {
    header .container {
        flex-wrap: nowrap;
    }

    nav .menu-toggle {
        display: block;
    }

    .nav-menu {
        display: none;
        flex-direction: column;
        width: 100%;
        background-color: var(--primary-color);
        position: absolute;
        top: 100%;
        left: 0;
        padding: 1rem 0;
        box-shadow: 0 2px 5px var(--shadow-light);
    }

    .nav-menu.active {
        display: flex;
    }

    .nav-menu li {
        text-align: center;
        width: 100%;
    }

    .nav-menu li a {
        padding: 0.8rem 1.5rem;
        display: block;
        border-bottom: 1px solid rgba(255, 255, 255, 0.1);
    }

    .nav-menu li:last-child a {
        border-bottom: none;
    }

    .hero {
        padding: 6rem 0;
    }

    .hero h1 {
        font-size: 2.5rem;
    }

    .hero p {
        font-size: 1.1rem;
    }

    .btn {
        padding: 0.8rem 2rem;
        font-size: 1.1rem;
    }

    .btn-secondary {
        margin-left: 0;
        margin-top: 1rem;
    }

    .section-title {
        font-size: 2rem;
    }

    .grid-3-cols, .team-grid, .portfolio-grid {
        grid-template-columns: 1fr;
    }

    .cta-banner h2 {
        font-size: 2.2rem;
    }

    .cta-banner p {
        font-size: 1.1rem;
    }

    .contact-grid {
        grid-template-columns: 1fr;
    }

    .footer-content {
        flex-direction: column;
        align-items: center;
    }

    .footer-section {
        text-align: center;
    }

    .footer-section ul {
        padding: 0;
    }
}

@media (max-width: 480px) {
    .hero h1 {
        font-size: 2rem;
    }

    .hero p {
        font-size: 1rem;
    }

    .btn {
        width: 100%;
        margin-bottom: 1rem;
    }

    .btn-secondary {
        margin-top: 0;
    }

    .section-title {
        font-size: 1.8rem;
    }

    .feature-card h3,
    .service-item-content h3,
    .portfolio-item-content h3 {
        font-size: 1.5rem;
    }

    .contact-info-block, .contact-form-wrapper {
        padding: 1.5rem;
    }

    .footer-section h3 {
        font-size: 1.4rem;
    }
}
