:root {
    --primary-color: #004080; /* Dark Blue */
    --secondary-color: #0066CC; /* Medium Blue */
    --accent-color: #FFC107; /* Amber/Gold */
    --text-color-dark: #333333;
    --text-color-light: #FFFFFF;
    --bg-light: #F8F8F8;
    --bg-white: #FFFFFF;
    --border-color: #E0E0E0;
    --shadow-light: rgba(0, 0, 0, 0.1);
    --shadow-medium: rgba(0, 0, 0, 0.2);
}

* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

html {
    scroll-behavior: smooth;
}

body {
    font-family: 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
    line-height: 1.6;
    color: var(--text-color-dark);
    background-color: var(--bg-light);
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
}

.container {
    max-width: 1200px;
    margin: 0 auto;
    padding: 0 1.5rem;
}

a {
    color: var(--secondary-color);
    text-decoration: none;
}

a:hover {
    text-decoration: underline;
}

img {
    max-width: 100%;
    height: auto;
    display: block;
}

/* Header */
header {
    background-color: var(--primary-color);
    color: var(--text-color-light);
    padding: 1rem 0;
    box-shadow: 0 2px 5px var(--shadow-light);
    position: sticky;
    top: 0;
    z-index: 1000;
}

header .container {
    display: flex;
    justify-content: space-between;
    align-items: center;
    flex-wrap: wrap;
}

.logo a {
    color: var(--text-color-light);
    font-size: 1.8rem;
    font-weight: bold;
    text-decoration: none;
    letter-spacing: 0.5px;
}

.logo a:hover {
    color: var(--accent-color);
    text-decoration: none;
}

nav .menu-toggle {
    display: none;
    background: none;
    border: none;
    color: var(--text-color-light);
    font-size: 2rem;
    cursor: pointer;
}

.nav-menu {
    list-style: none;
    display: flex;
    gap: 2rem;
}

.nav-menu li a {
    color: var(--text-color-light);
    font-weight: 500;
    font-size: 1.1rem;
    padding: 0.5rem 0;
    transition: color 0.3s ease, text-decoration 0.3s ease;
}

.nav-menu li a:hover,
.nav-menu li a.active {
    color: var(--accent-color);
    text-decoration: underline;
}

/* Main Content Sections */
main {
    padding-top: 0;
}

section {
    padding: 4rem 0;
    background-color: var(--bg-white);
    margin-bottom: 2rem;
}

section:nth-of-type(even) {
    background-color: var(--bg-light);
}

.section-title {
    text-align: center;
    font-size: 2.5rem;
    color: var(--primary-color);
    margin-bottom: 3rem;
    position: relative;
    padding-bottom: 1rem;
}

.section-title::after {
    content: '';
    position: absolute;
    left: 50%;
    bottom: 0;
    transform: translateX(-50%);
    width: 60px;
    height: 4px;
    background-color: var(--accent-color);
    border-radius: 2px;
}

/* Hero Section */
.hero {
    background: linear-gradient(rgba(0, 64, 128, 0.8), rgba(0, 64, 128, 0.8)), url('https://via.placeholder.com/1920x1080/004080/FFFFFF?text=Modern+IT+Infrastructure') no-repeat center center/cover;
    color: var(--text-color-light);
    text-align: center;
    padding: 8rem 0;
    position: relative;
    display: flex;
    align-items: center;
    min-height: 60vh;
}

.hero-content {
    max-width: 900px;
    margin: 0 auto;
}

.hero h1 {
    font-size: 3.8rem;
    margin-bottom: 1.5rem;
    line-height: 1.1;
    text-shadow: 2px 2px 4px var(--shadow-medium);
}

.hero p {
    font-size: 1.5rem;
    margin-bottom: 2.5rem;
    max-width: 800px;
    margin-left: auto;
    margin-right: auto;
}

.btn {
    display: inline-block;
    background-color: var(--accent-color);
    color: var(--primary-color);
    padding: 1rem 2.5rem;
    border-radius: 5px;
    font-size: 1.2rem;
    font-weight: bold;
    transition: background-color 0.3s ease, transform 0.3s ease;
    border: none;
    cursor: pointer;
}

.btn:hover {
    background-color: #E6B000;
    transform: translateY(-3px);
    text-decoration: none;
}

.btn-secondary {
    background-color: var(--secondary-color);
    color: var(--text-color-light);
    margin-left: 1rem;
}

.btn-secondary:hover {
    background-color: #005BBF;
}

/* Feature Cards / Grid Layouts */
.grid-3-cols {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
    gap: 2rem;
    margin-top: 3rem;
}

.feature-card {
    background-color: var(--bg-white);
    padding: 2rem;
    border-radius: 8px;
    box-shadow: 0 4px 10px var(--shadow-light);
    text-align: center;
    transition: transform 0.3s ease, box-shadow 0.3s ease;
}

.feature-card:hover {
    transform: translateY(-5px);
    box-shadow: 0 8px 15px var(--shadow-medium);
}

.feature-card img {
    width: 80px;
    height: 80px;
    margin: 0 auto 1.5rem;
    object-fit: contain;
    filter: drop-shadow(0 2px 5px rgba(0,0,0,0.1));
}

.feature-card h3 {
    color: var(--primary-color);
    font-size: 1.7rem;
    margin-bottom: 1rem;
}

.feature-card p {
    font-size: 1rem;
    color: #666;
}

/* Image-Text Section Layout */
.content-block {
    display: flex;
    flex-direction: column;
    gap: 3rem;
    align-items: center;
    margin-bottom: 3rem;
}

.content-block:nth-of-type(even) {
    flex-direction: column-reverse;
}

.content-block .text-content {
    flex: 1;
    padding: 1rem;
}

.content-block .image-wrapper {
    flex: 1;
    min-width: 300px;
    text-align: center;
}

.content-block .image-wrapper img {
    border-radius: 8px;
    box-shadow: 0 5px 15px var(--shadow-light);
}

.content-block h2 {
    font-size: 2.2rem;
    color: var(--primary-color);
    margin-bottom: 1rem;
}

.content-block p {
    font-size: 1.1rem;
    margin-bottom: 1.5rem;
    color: #555;
}

/* Call to Action */
.cta-banner {
    background-color: var(--secondary-color);
    color: var(--text-color-light);
    padding: 4rem 0;
    text-align: center;
    margin-bottom: 2rem;
}

.cta-banner h2 {
    font-size: 2.8rem;
    margin-bottom: 1.5rem;
    text-shadow: 1px 1px 3px var(--shadow-medium);
}

.cta-banner p {
    font-size: 1.3rem;
    margin-bottom: 2.5rem;
    max-width: 800px;
    margin-left: auto;
    margin-right: auto;
}

/* About Page Specific */
.team-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
    gap: 2rem;
    margin-top: 3rem;
}

.team-member {
    background-color: var(--bg-white);
    padding: 1.5rem;
    border-radius: 8px;
    box-shadow: 0 4px 10px var(--shadow-light);
    text-align: center;
}

.team-member img {
    width: 150px;
    height: 150px;
    border-radius: 50%;
    object-fit: cover;
    margin: 0 auto 1rem;
    border: 4px solid var(--accent-color);
}

.team-member h3 {
    font-size: 1.5rem;
    color: var(--primary-color);
    margin-bottom: 0.5rem;
}

.team-member p {
    color: #666;
    font-size: 1rem;
}

/* Services Page Specific */
.service-item {
    display: flex;
    flex-direction: column;
    background-color: var(--bg-white);
    border-radius: 8px;
    box-shadow: 0 4px 10px var(--shadow-light);
    overflow: hidden;
    transition: transform 0.3s ease, box-shadow 0.3s ease;
}

.service-item:hover {
    transform: translateY(-5px);
    box-shadow: 0 8px 15px var(--shadow-medium);
}

.service-item img {
    width: 100%;
    height: 250px;
    object-fit: cover;
    border-bottom: 1px solid var(--border-color);
}

.service-item-content {
    padding: 2rem;
}

.service-item-content h3 {
    font-size: 1.8rem;
    color: var(--primary-color);
    margin-bottom: 1rem;
}

.service-item-content p {
    font-size: 1rem;
    color: #555;
    margin-bottom: 1.5rem;
}

/* Portfolio Page Specific */
.portfolio-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
    gap: 2rem;
    margin-top: 3rem;
}

.portfolio-item {
    background-color: var(--bg-white);
    border-radius: 8px;
    box-shadow: 0 4px 10px var(--shadow-light);
    overflow: hidden;
    text-align: center;
    transition: transform 0.3s ease, box-shadow 0.3s ease;
}

.portfolio-item:hover {
    transform: translateY(-5px);
    box-shadow: 0 8px 15px var(--shadow-medium);
}

.portfolio-item img {
    width: 100%;
    height: 220px;
    object-fit: cover;
}

.portfolio-item-content {
    padding: 1.5rem;
}

.portfolio-item-content h3 {
    font-size: 1.6rem;
    color: var(--primary-color);
    margin-bottom: 0.5rem;
}

.portfolio-item-content p {
    font-size: 0.95rem;
    color: #666;
}

/* Contact Page Specific */
.contact-grid {
    display: grid;
    grid-template-columns: 1fr;
    gap: 3rem;
    margin-top: 3rem;
}

.contact-info-block {
    background-color: var(--bg-white);
    padding: 2.5rem;
    border-radius: 8px;
    box-shadow: 0 4px 10px var(--shadow-light);
}

.contact-info-block h3 {
    color: var(--primary-color);
    font-size: 1.8rem;
    margin-bottom: 1.5rem;
}

.contact-info-block p {
    display: flex;
    align-items: center;
    margin-bottom: 1rem;
    font-size: 1.1rem;
    color: #555;
}

.contact-info-block p strong {
    min-width: 80px;
    display: inline-block;
    color: var(--primary-color);
}

.contact-form-wrapper {
    background-color: var(--bg-white);
    padding: 2.5rem;
    border-radius: 8px;
    box-shadow: 0 4px 10px var(--shadow-light);
}

.contact-form-wrapper h3 {
    color: var(--primary-color);
    font-size: 1.8rem;
    margin-bottom: 1.5rem;
}

.contact-form label {
    display: block;
    margin-bottom: 0.5rem;
    font-weight: bold;
    color: var(--primary-color);
}

.contact-form input[type="text"],
.contact-form input[type="email"],
.contact-form textarea {
    width: 100%;
    padding: 1rem;
    margin-bottom: 1.5rem;
    border: 1px solid var(--border-color);
    border-radius: 5px;
    font-size: 1rem;
    transition: border-color 0.3s ease;
}

.contact-form input:focus,
.contact-form textarea:focus {
    border-color: var(--secondary-color);
    outline: none;
    box-shadow: 0 0 0 3px rgba(0, 102, 204, 0.2);
}

.contact-form textarea {
    resize: vertical;
    min-height: 120px;
}

.contact-form button {
    width: 100%;
    padding: 1rem;
    font-size: 1.2rem;
    border-radius: 5px;
    cursor: pointer;
}

.map-container {
    background-color: var(--bg-white);
    padding: 1.5rem;
    border-radius: 8px;
    box-shadow: 0 4px 10px var(--shadow-light);
    margin-top: 3rem;
    text-align: center;
}

.map-container h3 {
    color: var(--primary-color);
    font-size: 1.8rem;
    margin-bottom: 1.5rem;
}

.map-container img {
    width: 100%;
    max-height: 400px;
    object-fit: cover;
    border-radius: 8px;
}

/* Footer */
footer {
    background-color: var(--primary-color);
    color: var(--text-color-light);
    padding: 3rem 0 1.5rem;
    margin-top: 4rem;
}

.footer-content {
    display: flex;
    flex-wrap: wrap;
    justify-content: space-between;
    gap: 2rem;
    margin-bottom: 2rem;
}

.footer-section {
    flex: 1 1 280px;
    min-width: 250px;
}

.footer-section h3 {
    font-size: 1.6rem;
    margin-bottom: 1.5rem;
    color: var(--accent-color);
}

.footer-section p,
.footer-section ul li a {
    font-size: 0.95rem;
    color: rgba(255, 255, 255, 0.8);
    line-height: 1.8;
}

.footer-section ul {
    list-style: none;
}

.footer-section ul li a:hover {
    color: var(--text-color-light);
    text-decoration: underline;
}

.footer-bottom {
    text-align: center;
    padding-top: 1.5rem;
    border-top: 1px solid rgba(255, 255, 255, 0.2);
    font-size: 0.9rem;
    color: rgba(255, 255, 255, 0.7);
}

/* Responsive Design */
@media (max-width: 992px) {
    .hero h1 {
        font-size: 3rem;
    }

    .hero p {
        font-size: 1.3rem;
    }

    .nav-menu {
        gap: 1.5rem;
    }

    .content-block {
        flex-direction: column !important;
    }

    .content-block:nth-of-type(even) {
        flex-direction: column !important; /* Override for smaller screens */
    }

    .content-block .image-wrapper, .content-block .text-content {
        padding: 0;
    }

    .footer-section {
        flex-basis: 45%;
    }
}

@media (max-width: 768px) {
    header .container {
        flex-wrap: nowrap;
    }

    nav .menu-toggle {
        display: block;
    }

    .nav-menu {
        display: none;
        flex-direction: column;
        width: 100%;
        background-color: var(--primary-color);
        position: absolute;
        top: 100%;
        left: 0;
        padding: 1rem 0;
        box-shadow: 0 2px 5px var(--shadow-light);
    }

    .nav-menu.active {
        display: flex;
    }

    .nav-menu li {
        text-align: center;
        width: 100%;
    }

    .nav-menu li a {
        padding: 0.8rem 1.5rem;
        display: block;
        border-bottom: 1px solid rgba(255, 255, 255, 0.1);
    }

    .nav-menu li:last-child a {
        border-bottom: none;
    }

    .hero {
        padding: 6rem 0;
    }

    .hero h1 {
        font-size: 2.5rem;
    }

    .hero p {
        font-size: 1.1rem;
    }

    .btn {
        padding: 0.8rem 2rem;
        font-size: 1.1rem;
    }

    .btn-secondary {
        margin-left: 0;
        margin-top: 1rem;
    }

    .section-title {
        font-size: 2rem;
    }

    .grid-3-cols, .team-grid, .portfolio-grid {
        grid-template-columns: 1fr;
    }

    .cta-banner h2 {
        font-size: 2.2rem;
    }

    .cta-banner p {
        font-size: 1.1rem;
    }

    .contact-grid {
        grid-template-columns: 1fr;
    }

    .footer-content {
        flex-direction: column;
        align-items: center;
    }

    .footer-section {
        text-align: center;
    }

    .footer-section ul {
        padding: 0;
    }
}

@media (max-width: 480px) {
    .hero h1 {
        font-size: 2rem;
    }

    .hero p {
        font-size: 1rem;
    }

    .btn {
        width: 100%;
        margin-bottom: 1rem;
    }

    .btn-secondary {
        margin-top: 0;
    }

    .section-title {
        font-size: 1.8rem;
    }

    .feature-card h3,
    .service-item-content h3,
    .portfolio-item-content h3 {
        font-size: 1.5rem;
    }

    .contact-info-block, .contact-form-wrapper {
        padding: 1.5rem;
    }

    .footer-section h3 {
        font-size: 1.4rem;
    }
}
"}
